command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "5cdd28c0b7188730a4182f24932d3aaa901b9cae") { throw "main moved" }
$remoteHeads = git ls-remote --heads origin work/validation-churn-guards work/validation-churn-empty-evidence-fix
if ($LASTEXITCODE -ne 0) { throw "list remote work branches failed" }
$toDelete = @()
if ($remoteHeads -match "refs/heads/work/validation-churn-guards") { $toDelete += "work/validation-churn-guards" }
if ($remoteHeads -match "refs/heads/work/validation-churn-empty-evidence-fix") { $toDelete += "work/validation-churn-empty-evidence-fix" }
if ($toDelete.Count -gt 0) {
  git push origin --delete @toDelete
  if ($LASTEXITCODE -ne 0) { throw "persistent-checkout branch cleanup failed" }
}
Write-Host "VALIDATION_CHURN_TEMP_BRANCH_CLEANUP_PASS"
